    "content": "— 577 — \nCHAPITRE  VI \nVERBES \n28. Pour énoncer toutes  les  idées  de  mode  et de  temps exprimées  en  Fang, \ndeux procédés généraux sont employés  : \n1) l'addition  d'un  préfixe ou d'un  suffixe à la  forme simple  du  verbe. \n2) l'usage  des  verbes auxiliaires. \nLes formes construites  par une  addition  au  verbe simple sont  au  nombre  de \nsix, si l'on y  comprend  la  forme simple elle-même  : \n1) Forme simple yen, voir Infinitif \n2) Forme  ge yeñgé, vois Impératif \n3) Forme  l kel (de ke,  aller) \n4) Forme  a yena Temps  pa \n5) Forme  bo yenha Passif \n6) Forme nasale nyen \n29. Form"
