window.queryPdfKnowledge = function(query, targetLang = 'Fang') {
  if (!query || !query.trim()) return null;
  const q = query.trim().toLowerCase();
  
  // 1. Recherche dans le dictionnaire Fang -> Français
  const matchFang = (window.PDF_KNOWLEDGE_FANG || []).find(item => 
    item.fang.toLowerCase() === q || item.fang.toLowerCase().startsWith(q + ' ') || item.fr.toLowerCase() === q
  );

  // 2. Recherche dans le dictionnaire Français -> Fang
  const matchFrench = (window.PDF_KNOWLEDGE_FRENCH || []).find(item => 
    item.fr.toLowerCase() === q || item.fr.toLowerCase().startsWith(q + ' ') || item.fang.toLowerCase() === q
  );

  // 3. Recherche partielle / floue
  const partialFang = (window.PDF_KNOWLEDGE_FANG || []).find(item => 
    item.fang.toLowerCase().includes(q) || item.fr.toLowerCase().includes(q)
  );

  const partialFrench = (window.PDF_KNOWLEDGE_FRENCH || []).find(item => 
    item.fr.toLowerCase().includes(q) || item.fang.toLowerCase().includes(q)
  );

  const bestMatch = matchFang || matchFrench || partialFang || partialFrench;

  // 4. Recherche de règles grammaticales dans le PDF
  const grammarMatch = (window.PDF_GRAMMAR_NOTES || []).find(g => 
    g.content.toLowerCase().includes(q)
  );

  return {
    exactMatch: bestMatch ? {
      fang: bestMatch.fang,
      fr: bestMatch.fr,
      page: bestMatch.page
    } : null,
    grammarNote: grammarMatch ? { content: grammarMatch.content, page: grammarMatch.page } : null
  };
};

window.generateAIResponseFromPDF = function(prompt) {
  if (!prompt || !prompt.trim()) return "Mbolo ! Je suis l'assistant IA de Tradition IA. Posez-moi vos questions sur les langues et la culture du Gabon !";
  const p = prompt.trim().toLowerCase();

  // 1. Salutations et expressions de courtoisie
  if (p === 'mbolo' || p === 'bonjour' || p.includes('salut')) {
    return "👋 **Mbolo !** En Fang, Myènè et Punu, **Mbolo** est la salutation fraternelle universelle pour dire bonjour et souhaiter la bienvenue.";
  }

  if (p.includes('merci')) {
    return "🙏 Pour exprimer la gratitude :\n• **Fang** : *Akiba*\n• **Punu** : *Yine*\n• **Myènè** : *Ogula*\n• **Guisir** : *Akiba / Yine*\n• **Kota** : *Mbolo nzo*";
  }

  // 2. Extraction des mots-clés de la question
  const stopWords = ['comment', 'dit', 'on', 'en', 'le', 'la', 'les', 'de', 'du', 'des', 'un', 'une', 'que', 'veut', 'dire', 'traduis', 'traduction', 'fang', 'gabon', 'est', 'ce', 'pour', 'quel', 'quelle', 'dans'];
  const tokens = p.split(/[\s,?\.\!]+/).filter(w => w.length > 2 && !stopWords.includes(w));

  const results = [];
  for (const token of tokens) {
    const match = window.queryPdfKnowledge ? window.queryPdfKnowledge(token) : null;
    if (match && match.exactMatch) {
      results.push(match.exactMatch);
    }
  }

  if (results.length > 0) {
    let reply = `💡 **Vocabulaire et Traduction** :\n\n`;
    const seen = new Set();
    for (const res of results.slice(0, 5)) {
      const key = `${res.fang}-${res.fr}`;
      if (seen.has(key)) continue;
      seen.add(key);
      reply += `• **${res.fang}** ➔ *${res.fr}*\n`;
    }

    const matchGrammar = (window.PDF_GRAMMAR_NOTES || []).find(g => tokens.some(t => g.content.toLowerCase().includes(t)));
    if (matchGrammar) {
      reply += `\n✍️ **Note Grammaticale** :\n> ${matchGrammar.content.substring(0, 280).replace(/\n/g, ' ')}...`;
    }

    return reply;
  }

  // 3. Notions de grammaire
  if (p.includes('grammaire') || p.includes('verbe') || p.includes('conjugais') || p.includes('adverbe') || p.includes('accent') || p.includes('pluriel')) {
    const matchGrammar = (window.PDF_GRAMMAR_NOTES || []).find(g => tokens.some(t => g.content.toLowerCase().includes(t))) || window.PDF_GRAMMAR_NOTES[0];
    if (matchGrammar) {
      return `📖 **Règle Grammaticale** :\n\n${matchGrammar.content.substring(0, 450).replace(/\n/g, ' ')}...`;
    }
  }

  // 4. Recherche dictionnaire
  const fallback = window.queryPdfKnowledge ? window.queryPdfKnowledge(p) : null;
  if (fallback && fallback.exactMatch) {
    return `💡 **Traduction** :\n• **${fallback.exactMatch.fang}** ➔ *${fallback.exactMatch.fr}*`;
  }

  return `🤖 Je suis votre assistant Tradition IA. Concernant "${prompt}", vous pouvez me poser des questions sur le vocabulaire (ex: *eau, maison, enfant, manger, mbolo, akiba*), les expressions ou les règles de grammaire des langues gabonaises.`;
};

window.generateAIResponse = window.generateAIResponseFromPDF;
